  D.insectesAstuces = [
    { t: "Un coin sauvage", c: "Laissez un petit coin de jardin ou de cour sans tout tondre ni tout ranger : herbes, feuilles mortes, un peu de bois. Beaucoup d'amis s'y cachent et y passent l'hiver." },
    { t: "Des fleurs de mars à octobre", c: "Plantez des fleurs simples (pas trop \"doubles\") qui fleurissent à des moments différents : lavande, thym, bourrache, phacélie, souci, cosmos, fenouil, aneth. Les abeilles, les syrphes et les chrysopes y mangent le nectar et le pollen.", plantes: ["lavande", "thym", "bourrache", "phacelie", "souci", "cosmos", "fenouil", "aneth"] },
    { t: "Un tas de bois, de feuilles ou de pierres", c: "Un petit tas de bois mort, de feuilles ou de pierres sert de refuge aux carabes, aux staphylins, aux araignées et aux mille-pattes qui chassent. Mettez-le à l'abri, dans un coin tranquille." },
    { t: "Un hôtel à insectes bien fait", c: "Au soleil (plein sud ou sud-est), à l'abri du vent, entre 20 et 80 cm du sol. Bois non traité et non peint. Trous de 4 à 9 mm de large, jamais percés de part en part, dans du bois dur bien sec. Tiges creuses fermées au fond. Pommes de pin pour coccinelles et chrysopes. Il faut parfois plusieurs mois avant de voir des occupants." },
    { t: "Un point d'eau peu profond", c: "Une soucoupe remplie de cailloux ou de billes, avec un fond d'eau. Les insectes se posent sur les cailloux pour boire sans se noyer. Changez l'eau souvent." },
    { t: "Ne pas tout nettoyer en hiver", c: "Gardez des feuilles mortes au pied des arbustes et quelques tiges sèches jusqu'au printemps : coccinelles, chrysopes et abeilles solitaires y passent la mauvaise saison.", gestes: ["protection-hiver"] },
    { t: "Pas d'insecticide", c: "Un produit qui tue les pucerons tue aussi les coccinelles et les abeilles. Essayez d'abord un jet d'eau, de laisser faire les prédateurs, ou un soin naturel.", gestes: ["traitement-bio", "limaces-pucerons"] },
    { t: "Une terre vivante", c: "Paillage et compost nourrissent les vers de terre, les carabes et les cloportes qui travaillent la terre.", gestes: ["paillage", "compost-petit-espace"] }
  ];

